{"content":"import unittest

from go_counting import Board


class BoardTests(unittest.TestCase):
    def test_single_color_encloses_connected_region(self):
        board = Board(["BBBB", "B  B", "BBBB"])
        expected = ("B", {(1, 1), (2, 1)})
        self.assertEqual(board.territory(1, 1), expected)
        self.assertEqual(board.territory(2, 1), expected)

    def test_white_territory_at_board_edge(self):
        self.assertEqual(Board([" W", "WW"]).territory(0, 0),
                         ("W", {(0, 0)}))

    def test_mixed_border_is_neutral(self):
        self.assertEqual(Board(["B W"]).territory(1, 0),
                         ("", {(1, 0)}))

    def test_diagonal_stones_do_not_count(self):
        self.assertEqual(Board(["WBW", "B B", "WBW"]).territory(1, 1),
                         ("B", {(1, 1)}))

    def test_diagonal_empty_points_are_separate(self):
        self.assertEqual(Board([" B", "B "]).territory(0, 0),
                         ("B", {(0, 0)}))

    def test_occupied_points_have_no_territory(self):
        board = Board(["BW"])
        for x in range(2):
            with self.subTest(x=x):
                self.assertEqual(board.territory(x, 0), ("", set()))
        self.assertEqual(board.territories(), {"B": set(), "W": set(), "": set()})

    def test_board_without_stones_is_neutral(self):
        points = {(0, 0), (1, 0), (0, 1), (1, 1)}
        board = Board(["  ", "  "])
        self.assertEqual(board.territory(0, 0), ("", points))
        self.assertEqual(board.territories(), {"B": set(), "W": set(), "": points})

    def test_all_territories(self):
        board = Board([" B W "])
        self.assertEqual(board.territories(),
                         {"B": {(0, 0)}, "W": {(4, 0)}, "": {(2, 0)}})

    def test_invalid_coordinates(self):
        board = Board(["   ", "   "])
        for x, y in [(-1, 0), (0, -1), (3, 0), (0, 2), (10, 10)]:
            with self.subTest(x=x, y=y):
                with self.assertRaisesRegex(ValueError, "^Invalid coordinate$"):
                    board.territory(x, y)

    def test_empty_board(self):
        for rows in ([], [""]):
            with self.subTest(rows=rows):
                board = Board(rows)
                self.assertEqual(board.territories(),
                                 {"B": set(), "W": set(), "": set()})
                with self.assertRaisesRegex(ValueError, "^Invalid coordinate$"):
                    board.territory(0, 0)

    def test_large_region_does_not_require_recursion(self):
        board = Board([" " * 50 for _ in range(50)])
        owner, region = board.territory(0, 0)
        self.assertEqual(owner, "")
        self.assertEqual(region, {(x, y) for y in range(50) for x in range(50)})


if __name__ == "__main__":
    unittest.main()
